17	package io.helidon.tracing.opentelemetry;
18	
19	import java.util.Optional;
20	
21	import io.helidon.tracing.Span;
22	import io.helidon.tracing.Tracer;
23	import io.helidon.tracing.TracerBuilder;
24	
25	import org.junit.jupiter.api.Test;
26	
27	import static org.hamcrest.MatcherAssert.assertThat;
28	import static org.hamcrest.core.Is.is;
29	import static org.hamcrest.core.IsEqual.equalTo;
30	import static org.junit.jupiter.api.Assertions.assertThrows;
31	
32	/**
33	 * Test if baggage is handled correctly.
34	 */
35	class BaggageTest {
36	
37	    private final Tracer tracer = TracerBuilder.create("test-service").registerGlobal(false).build();
38	
39	    @Test
40	    void testBaggage() {
41	        Span span = tracer.spanBuilder("test-span").start();
42	        Span spanWithBaggage = span.baggage("key", "value");
43	        Optional<String> result = spanWithBaggage.baggage("key");
44	        assertThat(result.isPresent(), is(true));
45	        assertThat(result.get(), equalTo("value"));
46	        span.end();
47	    }
48	
49	    @Test
50	    void testBadBaggage() {
51	        Span span = tracer.spanBuilder("test-bad-span").start();
52	        assertThrows(NullPointerException.class, () -> span.baggage(null, "value"));
53	        assertThrows(NullPointerException.class, () -> span.baggage("key", null));
54	        assertThrows(NullPointerException.class, () -> span.baggage(null, null));
55	    }
56	}
