16	package io.helidon.tests.integration.tracerbaggage;
17	
18	import io.helidon.config.Config;
19	import io.helidon.tracing.HeaderConsumer;
20	import io.helidon.tracing.HeaderProvider;
21	import io.helidon.tracing.Span;
22	import io.helidon.tracing.Tracer;
23	import io.helidon.tracing.TracerBuilder;
24	import org.junit.jupiter.api.BeforeAll;
25	import org.junit.jupiter.api.Test;
26	
27	import java.util.ArrayList;
28	import java.util.List;
29	import java.util.TreeMap;
30	
31	import static org.hamcrest.CoreMatchers.containsString;
32	import static org.hamcrest.CoreMatchers.hasItem;
33	import static org.hamcrest.MatcherAssert.assertThat;
34	import static org.hamcrest.core.Is.is;
35	
36	class MainTest {
37	
38	    public static final String KEY = "fubar";
39	    public static final String VALUE = "1";
40	
41	    public static final String ANOTHER_KEY = "another";
42	    public static final String ANOTHER_VALUE = "value";
43	
44	    @BeforeAll
45	    static void prepareTracer() {
46	        Config config = Config.create();
47	
48	        TracerBuilder.create(config.get("tracing"))
49	                .serviceName("helidon-service")
50	                .registerGlobal(true)
51	                .build();
52	
53	
54	    }
55	
56	    /**
57	     * Test for: https://github.com/helidon-io/helidon/issues/6970
58	     */
59	    @Test
60	    void baggageCanaryMinimal() {
61	        Tracer tracer = Tracer.global();
62	        Span span = tracer.spanBuilder("baggageCanaryMinimal").start();
63	        // Set baggage and confirm that it's known in the span
64	        span.baggage(KEY, VALUE);
65	        span.baggage(ANOTHER_KEY, ANOTHER_VALUE);
66	        assertThat(span.baggage(KEY).orElse(null), is(VALUE));
67	        assertThat(span.baggage(ANOTHER_KEY).orElse(null), is(ANOTHER_VALUE));
68	
69	        // Inject the span (context) into the consumer
70	        HeaderConsumer consumer = HeaderConsumer
71	                .create(new TreeMap<>(String.CASE_INSENSITIVE_ORDER));
72	        tracer.inject(span.context(), HeaderProvider.empty(), consumer);
73	
74	        // Check baggage propagated
75	        List<String> result = new ArrayList<>();
76	        consumer.keys().forEach(result::add);
77	        assertThat(result, hasItem(containsString(KEY)));
78	        assertThat(result, hasItem(containsString(ANOTHER_KEY)));
79	
80	        //Check baggage value
81	        String fubar = result.stream().filter(e -> e.contains(KEY)).findFirst().orElseThrow();
82	        assertThat(consumer.get(fubar).orElseThrow(), is(VALUE));
83	        //Check another baggage
84	        String another = result.stream().filter(e -> e.contains(ANOTHER_KEY)).findFirst().orElseThrow();
85	        assertThat(consumer.get(another).orElseThrow(), is(ANOTHER_VALUE));
86	        span.end();
87	    }
88	
89	}
