package io.helidon.tracing.opentelemetry;

import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.Objects;
import java.util.function.BiConsumer;

import io.opentelemetry.api.baggage.Baggage;
import io.opentelemetry.api.baggage.BaggageBuilder;
import io.opentelemetry.api.baggage.BaggageEntry;
import io.opentelemetry.api.baggage.BaggageEntryMetadata;
import io.opentelemetry.context.Context;
import io.opentelemetry.context.Scope;

/**
 * A mutable implementation of the OpenTelemetry {@link io.opentelemetry.api.baggage.Baggage}.
 * <p>
 * The stock OpenTelemetry {@code Baggage} implementations are immutable, so once a baggage instance is stored in a
 * {@link io.opentelemetry.context.Context} it cannot be augmented without creating a new context scope. Helidon needs to be
 * able to add baggage entries to an existing span at any time without creating (and leaking) additional context scopes. This
 * mutable implementation lets a Helidon span own a single baggage instance whose entries can be updated in place; the same
 * instance is activated together with its span so that changes are visible through the current context and to propagators.
 */
class MutableOpenTelemetryBaggage implements Baggage {

    private final Map<String, BaggageEntry> values = new HashMap<>();

    MutableOpenTelemetryBaggage() {
    }

    private MutableOpenTelemetryBaggage(Map<String, BaggageEntry> values) {
        this.values.putAll(values);
    }

    @Override
    public Scope makeCurrent() {
        // Store this baggage in the current context and make that context current. This is invoked as part of activating
        // the owning span; it never mutates this baggage's entries.
        return Context.current().with(this).makeCurrent();
    }

    @Override
    public int size() {
        return values.size();
    }

    @Override
    public void forEach(BiConsumer<? super String, ? super BaggageEntry> consumer) {
        values.forEach(consumer);
    }

    @Override
    public Map<String, BaggageEntry> asMap() {
        return Collections.unmodifiableMap(values);
    }

    @Override
    public String getEntryValue(String entryKey) {
        BaggageEntry entry = values.get(entryKey);
        return entry != null ? entry.getValue() : null;
    }

    @Override
    public BaggageBuilder toBuilder() {
        BaggageBuilder builder = Baggage.builder();
        values.forEach((key, entry) -> builder.put(key, entry.getValue(), entry.getMetadata()));
        return builder;
    }

    // Add or update a baggage entry without touching the OpenTelemetry context.
    void baggage(String key, String value) {
        Objects.requireNonNull(key, "Baggage Key cannot be null");
        Objects.requireNonNull(value, "Baggage Value cannot be null");
        values.put(key, new MutableEntry(value, BaggageEntryMetadata.empty()));
    }

    private record MutableEntry(String value, BaggageEntryMetadata metadata) implements BaggageEntry {
        @Override
        public String getValue() {
            return value;
        }

        @Override
        public BaggageEntryMetadata getMetadata() {
            return metadata;
        }
    }
}
